<?php require __DIR__.'/head.php'; ?><nav class="topbar container"><a class="brand" href="<?=e(url())?>">a. agendashops</a><span class="muted">Agendamento online</span></nav><main class="container booking-layout"><aside class="business-card"><?php if($est['logo']):?><img class="business-logo" src="<?=e(url($est['logo']))?>" alt="Logo"><?php else:?><span class="large-avatar"><?=e(mb_substr($est['name'],0,1))?></span><?php endif;?><span class="eyebrow"><?=e($est['category'])?></span><h1><?=e($est['name'])?></h1><p><?=e($est['description'])?></p><p><?=e($est['address'])?></p><a class="text-link" href="https://wa.me/<?=e(strlen($est['phone'])<=11?'55'.$est['phone']:$est['phone'])?>" rel="noreferrer" target="_blank">Conversar no WhatsApp ↗</a><hr><p class="muted">Escolha seu momento.<br>A gente cuida dos detalhes.</p></aside><section class="panel"><span class="eyebrow">RESERVE SEU HORÁRIO</span><h2>Um tempo para você.</h2><?php if(!$services):?><p>Este estabelecimento ainda não disponibilizou serviços. Entre em contato pelo WhatsApp.</p><?php else:?><form id="booking-form" data-slug="<?=e($est['slug'])?>" data-base="<?=e(url())?>"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>01 · Escolha o serviço<select name="service" id="service" required><option value="">Selecione um serviço</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" data-price="<?=e(money($s['price']))?>" data-duration="<?=$s['duration']?>"><?=e($s['name'])?> · <?=$s['duration']?> min · <?=e(money($s['price']))?></option><?php endforeach;?></select></label><div class="service-descriptions"><?php foreach($services as $s):?><div data-service-detail="<?=$s['id']?>" hidden><?php if($s['image']):?><img class="service-image" src="<?=e(url($s['image']))?>" alt=""><?php endif;?><p><?=e($s['description'])?></p></div><?php endforeach;?></div><label>02 · Escolha o profissional<select name="professional" id="professional"><option value="0">Qualquer profissional disponível</option><?php foreach($professionals as $p):?><option value="<?=$p['id']?>" data-service="<?=$p['service_id']?>" hidden><?=e($p['name'])?></option><?php endforeach;?></select></label><label>03 · Escolha a data<input type="date" id="booking-date" name="date" required min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+'.(int)$settings['max_days'].' days'))?>"></label><fieldset><legend>04 · Horários disponíveis</legend><div id="slots" class="slots"><p class="muted">Selecione um serviço e uma data.</p></div></fieldset><div class="form-grid"><label>05 · Seu nome<input name="name" required maxlength="190" autocomplete="name"></label><label>WhatsApp com DDD<input name="phone" type="tel" required maxlength="30" autocomplete="tel"></label></div><label>E-mail <small>opcional</small><input name="email" type="email" maxlength="190" autocomplete="email"></label><label class="checkbox"><input name="privacy" type="checkbox" required> Li o <a href="<?=e(url('privacidade'))?>" target="_blank">aviso de privacidade</a> e autorizo o uso dos dados para este atendimento.</label><div id="booking-summary" class="notice" hidden></div><p id="booking-error" role="alert"></p><button id="review-booking" type="button">Revisar agendamento →</button><button id="confirm-booking" hidden>Confirmar agendamento ✓</button></form><?php endif;?></section></main><?php require __DIR__.'/foot.php'; ?>
